package org.hhn.topicgrouper.data;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

import org.hhn.topicgrouper.doc.Document;
import org.hhn.topicgrouper.doc.DocumentProvider;
import org.hhn.topicgrouper.doc.DocumentProvider.Vocab;
import org.hhn.topicgrouper.doc.impl.AbstractDocumentImpl;

import org.hhn.topicgrouper.util.RandomDirichlet1Dist;

/**
 * Generator of the synthetic "Topic Word Corpus" of the paper: every topic has its own
 * set of words, the documents are generated by the LDA generative process (Dirichlet
 * distributed topic proportions per document), optionally with homonyms attached to words of several topics.
 * The generator is itself the {@link DocumentProvider} of the generated documents. Words are the
 * numbers (as strings) of the word indices.
 */
public class TWCLDAPaperDocumentGenerator implements DocumentProvider<String>,
		Vocab<String> {
	/** The generated documents (unmodifiable). */
	private final List<Document<String>> documentsImmutable;
	/** Sampler of the topic proportions per document. */
	private final DirichletSampler dirichlet;
	/** Frequency of every word (index) in the generated documents. */
	private final int[] indexToFr;
	/** Total number of word occurrences in the generated documents. */
	private int size;
	/** Per topic: the distribution over its own words. */
	private final double[][] wordPerTopicDists;
	/** Per topic: the number of words of this and all preceding topics (the offset of the next topic's words). */
	private final int[] sumWordsUpToTopics;
	/** Number of ordinary words; homonyms have the indices from here on. */
	private final int baseWords;
	/** Per topic: the emission rate of all homonym tokens. */
	private final double[] homonymMassPerTopic;
	/** Per topic: the emission rate per homonym word (index). */
	private final Map<Integer, Double>[] homonymProbPerTopic;

	/**
	 * Generates the corpus of the paper with seed 45.
	 */
	public TWCLDAPaperDocumentGenerator() {
		this(new Random(45));
	}

	/**
	 * Generates the corpus of the paper (4 topics, 6000 documents of 30 words) with the given randomness.
	 *
	 * @param random the source of randomness
	 */
	public TWCLDAPaperDocumentGenerator(Random random) {
		this(random, new double[] { 5, 0.5, 0.5, 0.5 }, 6000, 100, 100, 30, 30,
				0, null, 0.5, 0.8);
	}

	/**
	 * Generates a corpus with a random number of words per topic.
	 *
	 * @param random the source of randomness
	 * @param dirichletAlpha Dirichlet parameter per topic (its length is the number of topics)
	 * @param docs number of documents
	 * @param minWordsPerTopic minimal number of words per topic
	 * @param maxWordsPerTopic maximal number of words per topic
	 * @param minWordsPerDoc minimal document length
	 * @param maxWordsPerDoc maximal document length
	 * @param homonyms number of homonyms (words shared by several topics)
	 * @param attachHomonymToTopicDistribution distribution of the number of topics a homonym is attached to
	 * @param minAttachProb minimal probability mass of a homonym in a topic
	 * @param maxAttachProb maximal probability mass of a homonym in a topic
	 */
	public TWCLDAPaperDocumentGenerator(Random random, double[] dirichletAlpha,
			int docs, int minWordsPerTopic, int maxWordsPerTopic,
			int minWordsPerDoc, int maxWordsPerDoc, int homonyms,
			double[] attachHomonymToTopicDistribution, double minAttachProb,
			double maxAttachProb) {
		this(random, dirichletAlpha, docs, computeWordsPerTopic(random,
				dirichletAlpha.length, minWordsPerTopic, maxWordsPerTopic),
				minWordsPerDoc, maxWordsPerDoc, homonyms,
				attachHomonymToTopicDistribution, minAttachProb, maxAttachProb);
	}

	/**
	 * Generates a corpus with the given number of words per topic. The topics a
	 * homonym is attached to are drawn once before the documents are generated;
	 * the <code>i</code>-th homonym is attached to the <code>i</code>-th word of
	 * each of these topics and emitted (with probability 1 minus the attach
	 * probability) whenever that word is emitted.
	 *
	 * @param random the source of randomness
	 * @param dirichletAlpha Dirichlet parameter per topic (its length is the number of topics)
	 * @param docs number of documents
	 * @param wordsPerTopic number of words per topic (one entry per topic)
	 * @param minWordsPerDoc minimal document length
	 * @param maxWordsPerDoc maximal document length
	 * @param homonyms number of homonyms (words shared by several topics)
	 * @param attachHomonymToTopicDistribution distribution of the number of topics (beyond two) a homonym is attached to, null for exactly two
	 * @param minAttachProb minimal attach probability of a homonym in a topic
	 * @param maxAttachProb maximal attach probability of a homonym in a topic
	 */
	public TWCLDAPaperDocumentGenerator(
			final Random random,
			double[] dirichletAlpha,
			int docs,
			int[] wordsPerTopic,
			int minWordsPerDoc,
			int maxWordsPerDoc,
			int homonyms,
			// Depending on the this distribution it is sampled to how many
			// words of
			// different topics the a homonym will be attached.
			// (at least two)
			// The topics are randomly chosen prior to document generation (so
			// independently of the documents).
			// The word to which a homonym will be attached per selected
			// document is
			// randomly chosen once (and remains fixed)
			double[] attachHomonymToTopicDistribution, double minAttachProb,
			double maxAttachProb) {
		List<Document<String>> documents = new ArrayList<Document<String>>();
		documentsImmutable = Collections.unmodifiableList(documents);

		RandomDirichlet1Dist dirichlet1Dist = new RandomDirichlet1Dist(random);

		wordPerTopicDists = new double[dirichletAlpha.length][];
		sumWordsUpToTopics = new int[wordsPerTopic.length];

		int allWords = 0;
		for (int i = 0; i < wordPerTopicDists.length; i++) {
			wordPerTopicDists[i] = dirichlet1Dist
					.nextDistribution(wordsPerTopic[i]);
			allWords += wordsPerTopic[i];
			sumWordsUpToTopics[i] = allWords;
		}
		indexToFr = new int[allWords + homonyms];
		baseWords = allWords;

		dirichlet = new DirichletSampler(random);
		int minMaxWordsPerDocDiff = maxWordsPerDoc - minWordsPerDoc;

		List<Integer> drawn = new ArrayList<Integer>();
		List<Integer> allTopics = new ArrayList<Integer>();
		for (int i = 0; i < dirichletAlpha.length; i++) {
			allTopics.add(i);
		}

		Map<Integer, Object[]> wordToHomonym = new HashMap<Integer, Object[]>();
		for (int i = 0; i < homonyms; i++) {
			allTopics.addAll(drawn);
			drawn.clear();
			int topicsForHomonym = (attachHomonymToTopicDistribution == null ? 0
					: nextDiscrete(attachHomonymToTopicDistribution, random)) + 2;
			for (int j = 0; j < topicsForHomonym; j++) {
				int topicIndex = random.nextInt(allTopics.size());
				drawn.add(allTopics.remove(topicIndex));
			}
			for (int topicIndex : drawn) {
				int wordInTopicIndex = i; // random.nextInt(wordsPerTopic[topicIndex]);
				int wordIndex = wordInTopicIndex
						+ (topicIndex == 0 ? 0
								: sumWordsUpToTopics[topicIndex - 1]);
				double attachProb = minAttachProb
						+ (maxAttachProb - minAttachProb) * random.nextDouble();
				Object[] value = new Object[] { allWords + i, attachProb };
				wordToHomonym.put(wordIndex, value);
			}
		}

		homonymMassPerTopic = new double[wordPerTopicDists.length];
		@SuppressWarnings("unchecked")
		Map<Integer, Double>[] perTopic = new Map[wordPerTopicDists.length];
		homonymProbPerTopic = perTopic;
		for (int t = 0; t < perTopic.length; t++) {
			perTopic[t] = new HashMap<Integer, Double>();
			int offset = t == 0 ? 0 : sumWordsUpToTopics[t - 1];
			for (int w = 0; w < wordPerTopicDists[t].length; w++) {
				Object[] info = wordToHomonym.get(offset + w);
				if (info != null) {
					double rate = wordPerTopicDists[t][w] * (1 - (Double) info[1]);
					perTopic[t].put((Integer) info[0], rate);
					homonymMassPerTopic[t] += rate;
				}
			}
		}

		for (int i = 0; i < docs; i++) {
			double[] topicPerDocDist = dirichlet.sample(dirichletAlpha);
			AbstractDocumentImpl<String> document = new AbstractDocumentImpl<String>(
					i) {
				@Override
				public DocumentProvider<String> getProvider() {
					return TWCLDAPaperDocumentGenerator.this;
				}
			};
			int wordsPerDoc = (minMaxWordsPerDocDiff == 0 ? 0 : random
					.nextInt(minMaxWordsPerDocDiff)) + minWordsPerDoc;

			for (int j = 0; j < wordsPerDoc; j++) {
				int topicIndex = nextDiscrete(topicPerDocDist, random);
				int wordInTopicIndex = nextDiscrete(
						wordPerTopicDists[topicIndex], random);
				int wordIndex = wordInTopicIndex
						+ (topicIndex == 0 ? 0
								: sumWordsUpToTopics[topicIndex - 1]);
				document.addWordOccurrence(wordIndex);
				indexToFr[wordIndex]++;
				size++;
				Object[] homonymInfo = wordToHomonym.get(wordIndex);
				if (homonymInfo != null) {
					if (random.nextDouble() >= (Double) homonymInfo[1]) {
						int homonym = (Integer) homonymInfo[0];
						document.addWordOccurrence(homonym);
						indexToFr[homonym]++;
						size++;
					}
				}
			}
			documents.add(document);
		}
	}

	/**
	 * The true word distribution of a topic.
	 *
	 * @param topicIndex the topic
	 * @param word a word of the vocabulary (the number of its index as a string)
	 * @return the true probability of the word given the topic (0 if the word does not belong to the topic).
	 *         Every emitted word of a topic that has a homonym attached is followed by the homonym with its attach
	 *         probability, so the probabilities are those of the token stream including the homonym tokens.
	 */
	public double getPwt(int topicIndex, String word) {
		int wordIndex = Integer.valueOf(word);
		double norm = 1 + homonymMassPerTopic[topicIndex];
		if (wordIndex >= baseWords) {
			Double rate = homonymProbPerTopic[topicIndex].get(wordIndex);
			return rate == null ? 0 : rate / norm;
		}

		int index = wordIndex
				- (topicIndex == 0 ? 0 : sumWordsUpToTopics[topicIndex - 1]);
		if (index < 0 || index >= wordPerTopicDists[topicIndex].length) {
			return 0;
		}
		return wordPerTopicDists[topicIndex][index] / norm;
	}

	/**
	 * Draws the number of words of every topic.
	 *
	 * @param random the source of randomness
	 * @param topics number of topics
	 * @param minWordsPerTopic minimal number of words per topic
	 * @param maxWordsPerTopic maximal number of words per topic
	 * @return the number of words per topic, uniformly drawn between min and max.
	 */
	protected static int[] computeWordsPerTopic(Random random, int topics,
			int minWordsPerTopic, int maxWordsPerTopic) {
		int[] wordsPerTopic = new int[topics];
		int minMaxWordsPerTopicDiff = maxWordsPerTopic - minWordsPerTopic;
		for (int i = 0; i < topics; i++) {
			wordsPerTopic[i] = (minMaxWordsPerTopicDiff == 0 ? 0 : random
					.nextInt(minMaxWordsPerTopicDiff)) + minWordsPerTopic;
		}
		return wordsPerTopic;
	}

	@Override
	public Vocab<String> getVocab() {
		return this;
	}

	@Override
	public List<Document<String>> getDocuments() {
		return documentsImmutable;
	}

	@Override
	public int getNumberOfWords() {
		return indexToFr.length;
	}

	@Override
	public String getWord(int index) {
		return String.valueOf(index);
	}

	@Override
	public int getIndex(String word) {
		return Integer.valueOf(word);
	}

	@Override
	public int getWordFrequency(int index) {
		return indexToFr[index];
	}

	@Override
	public int getSize() {
		return size;
	}

	/**
	 * Samples from a discrete distribution (the weights need not be normalized).
	 *
	 * @param probs the weights of the indices
	 * @param random the source of randomness
	 * @return an index drawn with probability proportional to probs.
	 */
	public static int nextDiscrete(double[] probs, Random random) {
		double sum = 0.0;
		for (int i = 0; i < probs.length; i++)
			sum += probs[i];

		double r = random.nextDouble() * sum;

		sum = 0.0;
		for (int i = 0; i < probs.length; i++) {
			sum += probs[i];
			if (sum > r)
				return i;
		}
		return probs.length - 1;
	}
}
